def get_elements_between(k):
    # Start with (1,0) and (0,1) to represent a_0 and a_1
    seq = [(1, 0), (0, 1)]
    for _ in range(k):
        new_seq = []
        for i in range(len(seq) - 1):
            new_seq.append(seq[i])
            new_seq.append((seq[i][0] + seq[i+1][0], seq[i][1] + seq[i+1][1]))
        new_seq.append(seq[-1])
        seq = new_seq
    return seq

for k in range(5):
    print(f"S_{k}: {get_elements_between(k)}")

